def matches(name, pattern):
    dp = [[False] * (len(name) + 1) for _ in range(len(pattern) + 1)]
    dp[0][0] = True
    for i, token in enumerate(pattern, 1):
        if token == '*':
            dp[i][0] = dp[i - 1][0]
        for j, char in enumerate(name, 1):
            if token == '*':
                dp[i][j] = dp[i - 1][j - 1]
            elif token == '?' or token == char:
                dp[i][j] = dp[i - 1][j - 1]
    return dp[-1][-1]

